# Optimize SSD: Enable TRIM, Disable Defrag on SSDs Write-Host "Optimizing SSD settings..." -ForegroundColor Cyan # Ensure TRIM is enabled $trimStatus = fsutil behavior query DisableDeleteNotify 2>&1 if ($trimStatus -match "0") { Write-Host " TRIM is already enabled." -ForegroundColor Gray } else { fsutil behavior set DisableDeleteNotify 0 2>&1 | Out-Null Write-Host " TRIM has been enabled." -ForegroundColor Gray } # Disable automatic defragmentation task Disable-ScheduledTask -TaskName "\Microsoft\Windows\Defrag\ScheduledDefrag" -ErrorAction SilentlyContinue Write-Host " Automatic defrag scheduled task disabled." -ForegroundColor Gray # Disable Storage Tiers optimization (SSD doesn't need tier optimization) Disable-ScheduledTask -TaskName "\Microsoft\Windows\Storage Tiers Management\Storage Tiers Optimization" -ErrorAction SilentlyContinue Write-Host " Storage Tiers optimization task disabled." -ForegroundColor Gray # Disable defrag for all SSD volumes $ssds = Get-PhysicalDisk | Where-Object { $_.MediaType -eq "SSD" -or $_.BusType -eq "NVMe" } if ($ssds) { foreach ($ssd in $ssds) { Write-Host " SSD detected: $($ssd.FriendlyName)" -ForegroundColor Gray } } Write-Host "SSD optimization complete: TRIM enabled, automatic defrag disabled." -ForegroundColor Green